describe('isPalindrome', () => {
  test.each([
    ['racecar', true],
    ['hello', false],
    ['madam', true],
    ['', true],
    ['a', true],
    ['ab', false],
  ])('isPalindrome("%s") === %s',
    (input, expected) => {
      expect(isPalindrome(input)).toBe(expected);
    }
  );
});

// Order Service test
test('publishes OrderCreated event', async () => {
  const bus = new InMemoryEventBus();
  const svc = new OrderService(bus);
  await svc.placeOrder({ item: 'Book', qty: 1 });
  expect(bus.getPublished()).toHaveLength(1);
  expect(bus.getPublished()[0].type).toBe('OrderCreated');
});
// Payment Service test (separate service)
test('handles OrderCreated event', async () => {
  const handler = new PaymentHandler();
  const evt = { type: 'OrderCreated', payload: { item: 'Book', qty: 1 } };
  const result = await handler.handle(evt);
  expect(result.status).toBe('payment_initiated');
});

test('token expires after 1 hour', () => {
  const clock = vi.useFakeTimers();
  clock.setSystemTime(
    new Date('2025-01-15T10:00:00Z')
  );

  const token = createToken({ userId: '123' });
  expect(token.isValid()).toBe(true);

  clock.advanceTimersByTime(60 * 60 * 1000 + 1);
  expect(token.isValid()).toBe(false);

  clock.useRealTimers();
});

